<?php

namespace Database\Factories;

use App\Models\Certificate;
use App\Models\Course;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * Code and issued_at are generated by Certificate::booted().
 *
 * @extends Factory<Certificate>
 */
class CertificateFactory extends Factory
{
    public function definition(): array
    {
        return [
            'user_id' => User::factory(),
            'course_id' => Course::factory()->published(),
            'student_name' => fn (array $attributes) => User::find($attributes['user_id'])->name,
            'course_title' => fn (array $attributes) => Course::find($attributes['course_id'])->title,
            'instructor_name' => fn (array $attributes) => Course::with('instructor')->find($attributes['course_id'])->instructor->name,
        ];
    }
}
